.com.br/img/img_prod/1445347/camisa_flamengo_blood_rubro_negro_masculino_1_20260818093945_1b0f11dc75f1.jpg", "tipo": "frente"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_flamengo_blood_rubro_negro_masculino_2_20260818093945_0ceff4b7dc29.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_flamengo_blood_rubro_negro_masculino_3_20260818093945_717c4450c2f4.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_flamengo_blood_rubro_negro_masculino_4_20260818093945_5aae7b65b2f8.jpg", "tipo": "extra"}], "video_url": null, "propriedades": {"Categoria": ["Camisa"], "Clubes": ["Flamengo"], "Gênero": ["Masculino"]}, "lancamento": false, "destaque": false, "coletado_em": "2026-11-24T20:16:44.930870+00:00"}, {"item_group_id": "OLD-P799", "id_loja": "799", "nome": "Camisa Portuguesa Retrô Campeão Paulista 1935 - Masculino", "slug": "camisa-portuguesa-retr-campeo-paulista-1935-masculino", "url": "https://www.oldensports.com.br/camisa-portuguesa-retr-campeo-paulista-1935-masculino", "marca": "Retrômania", "categoria": "Camisa", "departamento": "camisas", "clube": "Portuguesa", "genero": "masculino", "faixa_etaria": "adulto", "descricao": "Camisa Portuguesa Retrô Campeão Paulista 1935 - Masculino\nReviva a história gloriosa da Portuguesa com a camisa retrô de 1935, uma homenagem ao ano em que a Lusa conquistou seu primeiro título. Com seu design clássico, a camisa vermelha com golas e punhos verdes remete à tradição iniciada em 1920, quando os cinco clubes portugueses de São Paulo se fundiram, criando a Portuguesa. Em 1935, liderando a competição de forma incontestável, a Lusa enfrentou um desafio final que exigiu heroísmo e determinação. Com nomes lendários como Rossetti, Fiorotti e Oswaldo em campo, o time superou o Ypiranga em uma série histórica, garantindo o título com uma goleada de 5 x 2. Vestida com o mesmo uniforme, a Lusa repetiu o feito em 1936, consolidando sua força no futebol pa