aterial: 100% Poliéster\nEscudo: Bordado\nManga: Curta\nGola: Redonda\nMedidas Aproximadas (A x L):\nP: 67 x 49 cm\nM: 69 x 51 cm\nG: 71 x 53 cm\nGG: 73 x 55 cm\nXG: 75 x 57 cm", "medidas": "Medidas Aproximadas (A x L):\nP: 67 x 49 cm\nM: 69 x 51 cm\nG: 71 x 53 cm\nGG: 73 x 55 cm\nXG: 75 x 57 cm", "preco": 139.9, "preco_promocional": null, "preco_pix": 132.91, "parcelamento": "6x de R$ 23,32 Sem juros", "imagens": [{"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_argentina_retr_1986_home_masculino_1_20260514161406_9cdd6f7bf5ed.jpg", "tipo": "frente"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_argentina_retr_1986_home_masculino_2_20260514161406_50f19f4009bf.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_argentina_retr_1986_home_masculino_3_20260514161406_bfd79af5b58b.jpg", "tipo": "extra"}, {"url": "https://images.tcdn.com.br/img/img_prod/1445347/camisa_argentina_retr_1986_home_masculino_4_20260514161406_8cb3cb42a2eb.jpg", "tipo": "extra"}], "video_url": null, "propriedades": {"Categoria": ["Camisa"], "Clubes": ["Argentina"], "Gênero": ["Masculino"]}, "lancamento": false, "destaque": false, "coletado_em": "2026-11-24T20:16:44.930870+00:00"}]$dados$::jsonb) as x(item_group_id text, id_loja text, nome text, slug text, url text, marca text, categoria text, departamento text, clube text, genero text, faixa_etaria text, descricao text, medidas text, preco numeric, preco_promocional numeric, preco_pix numeric, parcelamento text, imagens jsonb, video_url text, propriedades jsonb, lancamento boolean, destaque boolean, coletado_em timestamptz)
on conflict (item_group_id) do update set id_loja = excluded.id_loja, nome = excluded.nome, slug = excluded.slug, url = excluded.url, marca = excluded.marca, categoria = excluded.categoria, departamento = excluded.departamento, clube = excluded.clube, genero = excluded.genero, faixa_etaria = excluded.faixa_etaria, descricao = excluded.descricao, medidas = excluded.medidas, preco = excluded.preco, preco_promocional = excluded.preco_promocional, preco_pix = excluded.preco_pix, parcelamento = excluded.parcelamento, imagens = excluded.imagens, video_url = excluded.video_url, propriedades = excluded.propriedades, lancamento = excluded.lancamento, destaque = excluded.destaque, coletado_em = excluded.coletado_em, ativo = true;

